# SPDX-License-Identifier: Apache-2.0
"""Generates `Proof/Wg0/Gen/CondEs<k>.lean`: `es<k>_cond_of_reads`, the condition of the
epilogue's output run of chunk `k` (`Gen.es<k>_cond`, 32 output words), from `c_esword`
(`Data/StrictEs.lean`). Run from the repository root."""

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
K = ROOT / "Kernels/FlashMlaSparseDecodeH64/Proof/Wg0"
nes = (K / "Gen/NumEs.lean").read_text()
HEAD = """-- SPDX-License-Identifier: Apache-2.0
-- Generated by Kernels/FlashMlaSparseDecodeH64/Gen/w0cond_es_gen.py; do not edit.
-- domain: valid-rows
module

public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data.StrictEs
public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen.Epi{k}

@[expose] public section

namespace PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data
open PTX PTX.Flow PTX.Proof PTX.Assumption PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen
  PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0

noncomputable section

"""
SEP = ",\n    "
for k in range(4):
    src = (K / f"Gen/Epi{k}.lean").read_text()
    base = int(re.search(r"theorem w0e_es%d .*?Rd \(V \((\d+) \+ i\)\)" % k, nes, re.S).group(1))
    SIG = (
        f"(V : Nat → Value) (O : Nat → ℝ) {{f : ℝ}}\n"
        f"    (hO : ∀ i < 64, Rd (V ({base} + i)) (O i))\n"
        f"    (hc : pairRead (V 3577) = some (.ok ((f : EReal), (f : EReal))))"
    )
    out = HEAD.format(k=k)
    for j in range(4):
        m = re.search(r"def es%d_items%d : List XItem := \[\n(.*?)\n\]\n" % (k, j), src, re.S)
        its = [re.sub(r"\s+", " ", x.strip()) for x in re.split(r",\n  (?=\.)", m.group(1))]
        assert len(its) == 32
        haves, terms = [], []
        for w in range(8):
            pk, ml = its[4 * w], its[4 * w + 1]
            d, a, b = map(int, re.findall(r"\d+", pk))
            i = a - base
            assert b == a + 1 and i % 2 == 0
            q = int(re.search(r"\[\(\.reg (\d+)\), \(\.reg (\d+)\)\]", ml).group(2))
            haves.append(
                f"  have c{w} := c_esword (p := {d}) (q := {q}) (by decide)\n"
                f"    (hO {i} (by norm_num)) (hO {i + 1} (by norm_num)) hc\n"
            )
            terms += [
                f"c{w}.left",
                f"c{w}.right.left",
                f"c{w}.right.right.left",
                f"c{w}.right.right.right",
            ]
        out += (
            f"/-- The condition of piece {j} of the epilogue's output chunk {k}. -/\n"
            f"theorem es{k}_{j}_cond_of_reads {SIG} :\n"
            f"    xCond (lookupD (es{k}_facts{j} V)) es{k}_items{j} := by\n"
            + "".join(haves)
            + f"  simp only [es{k}_items{j}, xCond]\n  exact ⟨{SEP.join(terms + ['trivial'])}⟩\n\n"
        )
    out += (
        f"/-- The output chunk {k}'s run has no fault outcome. -/\n"
        f"theorem es{k}_cond_of_reads {SIG} :\n    es{k}_cond V :=\n"
        f"  ⟨⟨⟨es{k}_0_cond_of_reads V O hO hc, es{k}_1_cond_of_reads V O hO hc⟩,\n"
        f"    es{k}_2_cond_of_reads V O hO hc⟩, es{k}_3_cond_of_reads V O hO hc⟩\n"
    )
    out += "\nend\nend PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data\n"
    (K / f"Gen/CondEs{k}.lean").write_text(out)
